INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (28, 'Hannan', '2024-12-10 01:00:47.677189', NULL, NULL, 'National University of Sciences and Technology (NUST) is a premier national university with global standing. Since its inception in 1991, it has developed into a comprehensive university with a focus on science and technology. Today, it is ranked among the top 100 world universities aged under 50 and No 1 engineering and technology university of Pakistan. Moreover, it is among the elite league of world universities in the disciplines of Electrical and Electronic Engineering and Computer Science and Information Systems, besides its recognition among the top universities from emerging economies, which speaks of the hard work of its leadership, faculty, researchers and students.
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (63, 'Hannan', '2025-02-23 13:43:39.198966', NULL, NULL, 'Vision
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (68, 'Hannan', '2025-02-23 13:43:39.198966', NULL, NULL, 'Al-Hamd Islamic University (AIU), established in 2005, is a private institution located in quetta, balochistan, Pakistan. Recognized by the Higher Education Commission (HEC) of Pakistan, AIU offers a diverse range of undergraduate and postgraduate programs across various disciplines. AIU is committed to providing quality education with an emphasis on Islamic teachings. The university aims to produce well-rounded academicians and individuals with strong ethical values.', 'HEC', '2024-08-18 00:00:00', 60000, 'Al- Hamd Islamic University, quetta', 160, NULL, 'https://www.aiu.edu.pk', NULL, NULL);
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (69, 'Hannan', '2025-02-23 13:43:39.198966', NULL, NULL, 'balochistan University of Information Technology & Management Sciences (BUITEMS), established in 2002, is a public research university located in quetta, balochistan, Pakistan. The university offers a diverse range of undergraduate and postgraduate programs across various disciplines, including engineering, information technology, and management sciences. BUITEMS is dedicated to providing quality education with a focus on research and development. The university operates multiple campuses, each specializing in different academic fields, and is committed to fostering an environment conducive to learning and innovation.', 'HEC,PEC', '2021-10-15 00:00:00', 48095.27, 'balochistan University Of It & Management Sciences, quetta', 116, NULL, 'https://www.buitms.edu.pk', NULL, NULL);
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (70, 'Hannan', '2025-02-23 13:43:39.198966', NULL, NULL, 'Bolan Medical College (BMC), established in 1972, is a public medical institution located in quetta, balochistan, Pakistan. It serves as a leading center for medical education and research in the region. BMC offers undergraduate and postgraduate programs in various medical and health sciences disciplines. The college is affiliated with the Bolan University of Medical and Health Sciences (BUMHS), which oversees its academic and administrative functions.', 'HEC,PMDC', '2024-08-19 00:00:00', 35030, 'Bolan Medical College / Bolan Hospital, quetta', 174, NULL, 'https://www.bmc.edu.pk', NULL, NULL);
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (71, 'Hannan', '2025-02-23 13:43:39.198966', NULL, NULL, 'Bolan University of Medical & Health Sciences (BUMHS), established in 2017, is a public medical university located in quetta, balochistan, Pakistan. It serves as the first and only medical university in the province, aiming to provide quality education and research opportunities in the medical and health sciences fields. 
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (72, 'Hannan', '2025-02-23 13:43:39.198966', NULL, NULL, 'balochistan has the privilege to house its first Women’s University at quetta. The need for a Women’s University in balochistan was felt from many decades, this need was finally realized when the Governor of balochistan, Mr. Owais Ahmed Ghani , promulgated an Ordinance No. 1 of 2004 to establish the Sardar Bahadur Khan Women’s University at quetta. On 26th August 2004, balochistan Provincial Assembly passed The Sardar Bahadur Khan Women’s University Act. The University has been established in Sardar Bahadur Khan Santorium very generously donated by the Pakistan Railways without any compensation. The premises of the University spread over 40 acres. Keys of the building were handed over to the Vice Chancellor on 18 March 2004, the building was witness to a historic transformation where it was given the status of balochistan''s first and Pakistan''s third Women''s University. From that day onwards, the Sardar Bahadur Khan Women''s University of balochistan has been striving to provide a safe haven to the women of balochistan and Pakistan who are interested in educational and intellectual pursuits.', 'HEC', '2024-08-26 00:00:00', 20178.55, 'Sardar Bahadur Khan Women University, quetta', 196, NULL, 'https://www.sbkwu.edu.pk', NULL, NULL);
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (73, 'Hannan', '2025-02-23 13:43:39.198966', NULL, NULL, 'The University of balochistan was established in October-1970 through an Ordinance issued by the then Governor balochistan. In June 1996, the balochistan Assembly passed an ACT called the University of balochistan ACT 1996, later-on the provincial assembly had passed a unified ACT in 2022 for all public sector Universities. Therefore, presently UoB is governed by same Act of 2022. The University of balochistan is the biggest general University of the Province imparting Higher Education to the entire population of the province in Science, Arts and Humanities.
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (74, 'Hannan', '2025-02-23 13:43:39.198966', NULL, NULL, 'The National University of Modern Languages was established as an institute in 1969 to help people communicate and understand each other in different oriental and occidental languages, to assimilate different cultures and to act as springboard for emerging disciplines. Initially, the institute provided language training facilities to personnel of armed forces and other government services of Pakistan. It was upgraded to University on May 29, 2000. In achieving this benchmark of a fully autonomous University, it has crossed many barriers and achieved a status of a seat of learning contributing new knowledge in local and global perspective and now teaches 27 oriental and occidental languages in addition to a number of emerging disciplines. Now, the University has a vibrant and well-grounded research program, offering MS/MPhil and PhD research degrees in various disciplines.', 'HEC', '2023-03-24 00:00:00', 39617.67, 'National University Of Modern Languages ( quetta Campus ), quetta', 123, NULL, 'https://www.numl.edu.pk/quetta', NULL, NULL);
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (75, 'Hannan', '2025-02-23 13:43:39.198966', NULL, NULL, 'National University of Sciences and Technology (NUST) is a premier national university with global standing. Since its inception in 1991, it has developed into a comprehensive university with a focus on science and technology. Today, it is ranked among the top 100 world universities aged under 50 and No 1 engineering and technology university of Pakistan. Moreover, it is among the elite league of world universities in the disciplines of Electrical and Electronic Engineering and Computer Science and Information Systems, besides its recognition among the top universities from emerging economies, which speaks of the hard work of its leadership, faculty, researchers and students.
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (44, 'Hannan', '2025-02-23 13:43:39.198966', NULL, NULL, 'Ilma University, formerly known as the Institute of Business & Technology (IBT), is a private institution in Karachi, Pakistan, established in 2001 and granted university status in 2017. The campus features modern facilities, including spacious classrooms, advanced labs, a digital library, a mosque, and sports clubs, fostering a supportive learning environment.
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (7, 'Hannan', '2024-12-10 01:00:47.677189', NULL, NULL, 'Alhamd Islamic University, established by the Alhamd Educational System (AES) in 1995, was founded with the vision of promoting education across various sectors. AES operates several educational institutions, including Balochistan Institute of Technology, BIT Girls College, Dar-e-Arqam School of Islam and Modern Sciences, Dar-e-Arqam Girls College, and Quran Research Academy. The university was formally chartered by the Government of Balochistan under Act II of 2005, granting it degree-awarding authority in multiple fields, including Islam, Science, Technology, Education, Law, Arts, and Engineering. Alhamd Islamic University aims to provide quality education while integrating Islamic values with modern learning. It is known for its commitment to academic excellence, research, and community service, serving as a key educational institution in the region.', 'HEC', '2023-02-28 00:00:00', 57000, 'Alhamd Islamic University [ibd], Islamabad', 75, '2025-04-15 00:00:00', 'https://www.aiu.edu.pk', '2025-04-15 00:00:00', NULL);
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (42, 'Hannan', '2025-02-23 13:43:39.198966', NULL, NULL, 'The National College of Arts (NCA), founded in 1875, is Pakistan''s premier institution for higher education in the fields of fine arts, design, and architecture. Renowned for its legacy and academic excellence, NCA offers diverse programs that cultivate creativity, critical thinking, and practical skills. The college prepares students for successful careers in various art forms, architecture, and design disciplines, with a distinguished faculty guiding them toward professional achievements. With a focus on both traditional techniques and modern innovations, NCA continues to shape the cultural landscape of Pakistan.', 'HEC,PEC,NACAD', '2024-09-10 00:00:00', 109655.43, 'National College Of Arts, Lahore', 75, '2024-08-26 00:00:00', 'https://www.nca.edu.pk', '2024-09-10 00:00:00', NULL);
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (8, 'Hannan', '2024-12-10 01:00:47.677189', NULL, NULL, 'National College of Business Administration and Economics (NCBA&E) was established in 1994 as a private institution with a focus on delivering excellence in teaching and fostering strong partnerships with industry. The college quickly earned recognition in management studies and expanded its academic offerings with the introduction of Computer Science in 1997. In 2002, NCBA&E received its charter from the Government of Punjab, further solidifying its status as a leader in higher education. 
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (9, 'Hannan', '2024-12-10 01:00:47.677189', NULL, NULL, 'NUR International University (NIU), located in Lahore, Pakistan, offers an innovative and globally-oriented education with a strong emphasis on research and academic excellence. The university integrates Eastern and Western educational principles to develop well-rounded professionals equipped to lead in various sectors. NIU is committed to preparing students for successful careers by providing them with a broad knowledge base, critical thinking skills, and hands-on learning experiences. With a state-of-the-art campus and a focus on integrity and innovation, NIU aims to make a positive impact on society through education', 'HEC,PNC', '2024-09-30 00:00:00', 167257.5, 'Nur International University, Lahore', 177, '2024-10-17 00:00:00', 'https://www.niu.edu.pk', '2024-10-17 00:00:00', NULL);
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (10, 'Hannan', '2024-12-10 01:00:47.677189', NULL, NULL, 'The Pakistan Institute of Fashion and Design (PIFD) in Lahore is a public sector university, chartered by the Government of Pakistan, dedicated to fostering excellence in fashion, design, and allied disciplines. Located in Johar Town, Lahore, PIFD is a prominent institution specializing in design education, offering both undergraduate and postgraduate programs across various creative fields. These programs include Fashion Design, Textile Design, Leather Accessories and Footwear, Furniture Design, and Jewellery Design, along with an MPhil in Art and Design.
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (11, 'Hannan', '2024-12-10 01:00:47.677189', NULL, NULL, 'Punjab Tianjin University of Technology (PTUT) in Lahore stands as Pakistan''s first public sector technological university dedicated to bridging the gap between academic learning and industry needs. Established in collaboration with the Government of Punjab and three prestigious Tianjin universities in China, PTUT aims to revolutionize technical education. The university provides advanced programs in engineering technology, emphasizing applied knowledge and practical skills tailored for industry employment. Its focus on hands-on training makes it a pioneering institution for producing skilled technologists in fields like mechanical, civil, electrical, and automotive engineering, as well as fashion and textile designÔÇï', 'HEC,TEVTA', '2024-07-25 00:00:00', 25500, 'Punjab Tianjin University Of Technology, Lahore', 185, NULL, 'https://www.ptut.edu.pk', '2024-07-25 00:00:00', NULL);
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (45, 'Hannan', '2025-02-23 13:43:39.198966', NULL, NULL, 'Indus University, located in Karachi, Pakistan, was established in 2004 as the Indus Institute of Higher Education and was granted university status in 2012. The university offers undergraduate, graduate, and postgraduate programs across various disciplines, including engineering, business administration, film and TV, and art and design. It is recognized by the Higher Education Commission of Pakistan and has received a five-star ranking from the Charter Inspection and Evaluation Committee of the Sindh Government. Indus University has also established international collaborations with over 40 universities worldwide', 'HEC,PEC,NBEAC,NCEAC', '2024-11-30 00:00:00', 125732, 'Indus University, karachi', 99, NULL, 'https://www.indus.edu.pk', '2024-11-30 00:00:00', NULL);
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (12, 'Hannan', '2024-12-10 01:00:47.677189', NULL, NULL, 'Established in March 2011, Qarshi University has swiftly established itself as a progressive institution focused on delivering quality education. Obtaining its charter the same year, the university embarked on a journey of rapid expansion and development, aiming to become a leading center of higher education. Backed by Qarshi Industries, the university benefits from a solid foundation that supports its sustainable growth and achievement of strategic goals.
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (13, 'Hannan', '2024-12-10 01:00:47.677189', NULL, NULL, 'Rashid Latif Khan University (RLKU), located in Lahore, Pakistan, is a private institution founded with a mission to deliver quality education across multiple disciplines. The university offers programs in various fields such as medical sciences, allied health, business administration, law, computer science, and social sciences. It is known for its commitment to academic excellence, robust faculty, and extensive infrastructure that supports both academic and extracurricular activities. RLKU aims to provide a student-centered learning environment with modern facilities, including a hospital, library, and wellness center. Additionally, students have opportunities to engage in various student societies and clubs that foster personal and professional development.
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (14, 'Hannan', '2024-12-10 01:00:47.677189', NULL, NULL, 'Superior University Lahore, established in 2003, has emerged as a prominent educational institution dedicated to fostering innovation in higher education. The universityÔÇÖs commitment to providing quality education is evident in its diverse range of academic offerings, which include undergraduate, postgraduate, and professional degree programs across multiple disciplines. Its academic faculties encompass business, economics, computer science, engineering, allied health sciences, art and design, and more.
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (15, 'Hannan', '2024-12-10 01:00:47.677189', NULL, NULL, 'The University of Lahore (UOL) is a leading private institution established in 1999. It has grown significantly, with campuses in multiple locations across Pakistan, including Lahore, Islamabad, Sargodha, and Gujrat, and even extending internationally to Uganda. UOL offers a wide range of undergraduate, graduate, and doctoral programs across its faculties, which include engineering, management sciences, law, arts and social sciences, and health sciences.
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (39, 'Hannan', '2024-12-10 01:00:47.677189', NULL, NULL, 'Lahore City University is the project of Al-Rehman Education System (Pvt) Ltd. which is located in Saggian Road Lahore. Mian Muhammad Mushtaq, Cheif Executive of Al-Rehamn Developers has done wonder for the projects he has developed. His knowledge and expertise has made him who he is today.', 'HEC,PEC,NTC', NULL, 110000, 'Lahore City University, Lahore', 70, NULL, 'https://www.lcu.edu.pk', '2024-12-08 00:00:00', NULL);
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (16, 'Hannan', '2024-12-10 01:00:47.677189', NULL, NULL, 'University College of Medicine & Dentistry offers one of the most forward-looking educational environments in Medicine & Dentistry in the country.
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (17, 'Hannan', '2024-12-10 01:00:47.677189', NULL, NULL, 'The University of Central Punjab (UCP) is a private institution in Lahore, Pakistan, chartered in 2002 by the Government of Punjab. It was initially formed through the merger of institutions under the Punjab Group of Colleges, including the Punjab College of Business Administration (PCBA), Punjab Institute of Computer Sciences (PICS), and others.
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (18, 'Hannan', '2024-12-10 01:00:47.677189', NULL, NULL, 'Aga Khan University (AKU) is a prestigious institution dedicated to improving quality of life globally, with a focus on health, education, and community development. Founded in 1983 as Pakistan''s first private university, AKU is a not-for-profit institution and part of the Aga Khan Development Network. The University aims to address local and global challenges through world-class education, innovative research, and exceptional healthcare delivery. AKUÔÇÖs mission emphasizes empowering women, supporting the disadvantaged, promoting pluralism, and working with global and local partners to achieve shared goals.
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (20, 'Hannan', '2024-12-10 01:00:47.677189', NULL, NULL, 'Benazir Bhutto Shaheed University Lyari (BBSUL), located in karachi, Sindh, Pakistan, was established in 2010 to provide higher education opportunities, especially for the youth in underprivileged areas. The university''s mission focuses on fostering education and development in various disciplines while promoting socioeconomic advancement. It emphasizes accessibility, offering stipends and scholarships to support students, particularly female learners, from low-income backgrounds.
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (21, 'Hannan', '2024-12-10 01:00:47.677189', NULL, NULL, 'The Dadabhoy Institute of Higher Education (DIHE) was established in 2003, and received its charter as a degree awarding institute from the Government of Sindh, Pakistan through an act of Sindh Assembly. On the basis of its well designed academic programs, well qualified teaching faculty and state-of-art facilities; in 2005, DIHE was placed in the W ÔÇÿAÔÇÖ category by the Higher Education Commission. DIHE aspires to integrate academic excellence in different areas of studies to ensure unique educational experience. It incorporates the value based education system and best academic practices along with various technical as well as cultural initiatives in all the programs being offerd.
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (22, 'Hannan', '2024-12-10 01:00:47.677189', NULL, NULL, 'Dawood University of Engineering and Technology (DUET) in karachi, Pakistan, is a prominent institution that specializes in engineering, technology, and applied sciences. Established in 1962, it initially began as Dawood College of Engineering and Technology, envisioned by its founder, Mr. Ahmed Dawood, to support PakistanÔÇÖs industrial development. It became a university in 2013 through an Act of the Sindh Provincial Assembly.
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (23, 'Hannan', '2024-12-10 01:00:47.677189', NULL, NULL, 'DHA Suffa University (DSU), established in the year 2012, has systematically taken giant strides to become the institution of choice in Pakistan. The university offers undergraduate, graduate and doctoral programs in Engineering, Computer Science, Management Sciences, Humanities and Social Sciences and newly launched programs BS Business Analytics & Programming, BS Computational & Industrial Mathematics, BS Accounting & Finance, BS Software Engineering, BS Data Sciences, BE Civil Engineering, BS International Relations, BS English and BS Psychology. At DSU, students receive quality education and become part of an academic community sharing diverse interests. DSU not only helps to expand the mental faculties of individuals but also transforms them into more open-minded, accepting and involved citizens. With a vision to move forward, DSU intends on becoming a globally recognized institution of higher education and research by extending the frontiers of knowledge and contributing towards grooming the scholars of tomorrow. From the expansion of infrastructure to the development of technology, revamping of curricula to the formation of pedagogy, addition of foreign qualified faculty to the international collaborations multi face, DSU has been committed to provide well-equipped engineers, computer scientists, entrepreneurs and corporate leaders.', 'PEC,NCEAC,NBEAC,CIEC', '2024-07-21 00:00:00', 144028.57, 'Dha Suffa University(main Campus), karachi', 77, NULL, 'https://www.dsu.edu.pk', '2024-07-21 00:00:00', NULL);
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (24, 'Hannan', '2024-12-10 01:00:47.677189', NULL, NULL, 'The Dow University of Health Sciences (DUHS), located in karachi, Pakistan, is one of the country''s premier medical institutions. Established initially as Dow Medical College in 1945, it was restructured into DUHS in 2003. The university focuses on producing highly qualified medical and health professionals and is recognized for its emphasis on integrating research and community service within its academic framework.
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (25, 'Hannan', '2024-12-10 01:00:47.677189', NULL, NULL, 'Greenwich University, established in 1987, is a private educational institution located in karachi, Pakistan. Initially focused on management sciences, the university expanded over time to include faculties like Social Sciences, Humanities, Media Studies, and Fashion. In 1998, it became an autonomous degree-awarding institution under the Act of the Sindh Government.
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (26, 'Hannan', '2024-12-10 01:00:47.677189', NULL, NULL, 'Habib University in karachi is a premier institution dedicated to providing a world-class undergraduate education in liberal arts and sciences. Established with the vision to be South AsiaÔÇÖs leading liberal arts university, it emphasizes intellectual growth, interdisciplinary learning, and societal engagement. Its mission focuses on shaping futures by offering rigorous, contextually relevant education to talented students, regardless of financial or social barriers.
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (43, 'Hannan', '2025-02-23 13:43:39.198966', NULL, NULL, 'Hamdard University, established in 1991 by philanthropist Hakim Said, is one of Pakistan''s earliest private research institutions. With campuses in Karachi and Islamabad, it offers a diverse range of undergraduate and postgraduate programs across various disciplines. The university is home to the Bait-ul-Hikmah library, one of South Asia''s largest research libraries, housing over half a million books, some dating back to the 17th century. Hamdard University comprises eight faculties, nine research institutes, three teaching hospitals, and three affiliated engineering institutes. Its programs are accredited by bodies such as the Higher Education Commission (HEC), Pakistan Engineering Council (PEC), and Pakistan Medical and Dental Council (PMDC).', 'HEC,PMDC,PEC,PCP,NCEAC,NBEAC,SHEC,', '2024-07-13 00:00:00', 133537.42, 'Hamdard University, karachi', 66, NULL, 'https://www.hamdard.edu.pk', '2024-07-13 00:00:00', NULL);
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (46, 'Hannan', '2025-02-23 13:43:39.198966', NULL, NULL, 'The Indus Valley School of Art and Architecture (IVS), established in 1989 in Karachi, is a private, non-profit institution dedicated to excellence in Fine Arts, Design, and Architecture. Granted an independent charter in 1994, IVS offers undergraduate programs in Architecture, Interior Design, Fine Arts, Communication Design, Textile Design, and Fashion Design. The school fosters creativity, critical thinking, and interdisciplinary collaboration. Managed by an Executive Committee under a Board of Governors, IVS provides a vibrant learning environment that prepares students for innovative careers in the arts and design industries.', 'HEC,PCATP', '2024-07-31 00:00:00', 350000, 'Indus Valley School Of Art And Architecture, karachi', 18, NULL, 'https://www.indusvalley.edu.pk', '2024-07-31 00:00:00', NULL);
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (47, 'Hannan', '2025-02-23 13:43:39.198966', NULL, NULL, 'The Institute of Business Administration (IBA) in Karachi, established in 1955, is Pakistan''s oldest business school and was the first outside North America. Initially founded with support from the University of Pennsylvania and the University of Southern California, IBA has evolved into a premier public sector institution offering a range of undergraduate, graduate, and doctoral programs. These include degrees in Business Administration, Accounting and Finance, Computer Science, Economics, and Social Sciences. IBA is accredited by the Higher Education Commission of Pakistan and is a member of the Association of Commonwealth Universities. The institute emphasizes discipline, creativity, tolerance, integrity, and teamwork, aiming to cultivate thought leaders equipped to navigate the complexities of the modern world', 'HEC,AMBA,NBEAC,SAQS,IACBE', '2024-07-12 00:00:00', 104120.98, 'Institute Of Business Administration [khi], karachi', 7, NULL, 'https://www.iba.edu.pk', '2024-07-12 00:00:00', NULL);
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (48, 'Hannan', '2025-02-23 13:43:39.198966', NULL, NULL, 'The Institute of Business Management (IoBM), established in 1995 in Karachi, Pakistan, is a private institution that offers a wide range of undergraduate, graduate, and doctoral programs. Initially founded as the College of Business Management, IoBM has expanded into four colleges: the College of Business Management (CBM), the College of Economics and Social Development (CESD), the College of Computer Science and Information Systems (CCSIS), and the College of Engineering Sciences (CES). IoBM is recognized by the Higher Education Commission (HEC) of Pakistan and holds membership in various international and national professional bodies, including the Association of Commonwealth Universities and the International Association of Universities. Committed to innovation, research, and societal development, IoBM strives to be a leading educational institution both in Pakistan and globally.', 'HEC,BAAC,NBEAC,ACU,IAU', '2022-07-28 00:00:00', 132347.69, 'Institute Of Business Management, karachi', 10, NULL, 'https://www.iobm.edu.pk', '2022-07-28 00:00:00', NULL);
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (49, 'Hannan', '2025-02-23 13:43:39.198966', NULL, NULL, 'Iqra University, established in 1998, is a private university located in Karachi, Pakistan, with additional campuses in Islamabad and Peshawar. The university offers a wide range of undergraduate, graduate, and doctoral programs in fields such as business administration, engineering, and social sciences. Iqra University is dedicated to fostering technical skills, critical thinking, and a sense of public duty among its students, with the goal of contributing to a progressive society. Its main campus in Karachi is a purpose-built, 13-story educational facility, featuring state-of-the-art classrooms, advanced laboratories, modern libraries, and dedicated study areas, creating an optimal environment for academic excellence. Iqra University has been recognized for its academic achievements and was ranked as the number one business school in Pakistan by the Higher Education Commission in 2016.', 'HEC,NBEAC,NCEAC,PEC', '2023-01-21 00:00:00', 98707.58, 'Iqra University [kch], karachi', 12, NULL, 'https://www.iqra.edu.pk', '2023-01-21 00:00:00', NULL);
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (50, 'Hannan', '2025-02-23 13:43:39.198966', NULL, NULL, 'Jinnah Sindh Medical University (JSMU), located in Karachi, Pakistan, was established on June 1, 2012, evolving from the esteemed Sindh Medical College. As the largest medical university in Sindh, JSMU has 11 constituent institutes and around 35 affiliated colleges, catering to over 6,000 students in medical and allied health sciences. The university offers various undergraduate and postgraduate programs through institutions such as Sindh Medical College, APPNA Institute of Public Health, Institute of Pharmaceutical Sciences, and Institute of Nursing & Midwifery, among others. JSMU is committed to modernizing medical education by regularly updating its curriculum and facilities. It provides clinical training through affiliations with leading healthcare institutions, including Jinnah Postgraduate Medical Centre (JPMC), National Institute of Child Health (NICH), and National Institute of Cardiovascular Diseases (NICVD). Notably, JSMU is the first public sector medical university in Pakistan to implement computer-based examinations for all students. The university envisions becoming a socially accountable, nationally benchmarked institution focused on improving healthcare through education, leadership, research, and community service. Recognized by the Higher Education Commission (HEC) of Pakistan, JSMU continues to advance healthcare education and services in the region.', 'HEC,PMDC,CPSP,APQN', '2024-12-12 00:00:00', 139688.33, 'Jinnah Sindh Medical University, karachi', 6, NULL, 'https://www.jsmu.edu.pk', '2024-12-12 00:00:00', NULL);
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (51, 'Hannan', '2025-02-23 13:43:39.198966', NULL, NULL, 'Jinnah University for Women (JUW), established in 1998 under the Anjuman-e-Islamia Trust founded by Al-Haj Moulvi Reyazuddin Ahmed (T.I), is Pakistan''s first women''s university. Located in Karachi, JUW offers a range of undergraduate, graduate, and doctoral programs across various disciplines. The university comprises five faculties: Science, Pharmacy, Social Sciences, Business Administration, Commerce & Economics, and Allied Medical Sciences. JUW is committed to empowering women through quality education, fostering intellectual and personal growth, and preparing students to become transformational citizens with strong ethical, cultural, and religious values. The campus features modern facilities, including a central library with over 60,000 books, specialized laboratories, and dedicated research centers. The university also provides scholarships on a merit-cum-need basis to support deserving students. JUW is recognized by the Higher Education Commission of Pakistan and continues to play a pivotal role in promoting female education in the country.', 'HEC,NBEAC,ISO', '2024-11-15 00:00:00', 35408.31, 'Jinnah University For Women, karachi', 13, NULL, 'https://www.juw.edu.pk', '2025-11-15 00:00:00', NULL);
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (52, 'Hannan', '2025-02-23 13:43:39.198966', NULL, NULL, 'Karachi Institute of Economics and Technology (KIET), established in 1997, is a private higher education institution located in Karachi, Pakistan. Recognized by the Higher Education Commission (HEC) of Pakistan, KIET offers a diverse range of undergraduate, graduate, and doctoral programs across various disciplines, including engineering, business administration, computer science, media arts, and humanities. The institute is committed to providing quality education and fostering research and innovation. KIET operates multiple campuses, including the main campus at PAF Base Korangi Creek, a city campus on Shahrah-e-Faisal, and a North Nazimabad campus, all equipped with modern facilities to support academic and extracurricular activities. The institute has been recognized for its contributions to higher education and has established strong industry linkages to enhance learning and career opportunities for its students.', 'HEC,PEC,NCEAC,NBEAC,NTC,', '2024-01-06 00:00:00', 81861.22, 'karachi Institute Of Economics & Technology, karachi', 21, NULL, 'https://www.pafkiet.edu.pk', '2025-01-06 00:00:00', NULL);
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (53, 'Hannan', '2025-02-23 13:43:39.198966', NULL, NULL, 'Karachi School of Business & Leadership (KSBL), established in 2010, is an independent graduate business school located in Karachi, Pakistan. Founded through a strategic collaboration between the Karachi Education Initiative (KEI) and the Cambridge Judge Business School, KSBL offers a range of graduate programs, including MBA, Executive MBA, MS in Business Analytics, and various undergraduate programs such as BS in Management & Entrepreneurship, BS in Information Technology Management, BS in Accounting & Finance, and BS in Computer Science. The school operates from a purpose-built campus designed by William McDonough Partners, inaugurated in 2013. In December 2018, KSBL launched the Engro Leadership Academy, aiming to develop the next generation of Pakistani leadership. KSBL is committed to providing future business leaders with the knowledge and skills to compete in a global marketplace, emphasizing ethical leadership, entrepreneurialism, technological proficiency, global awareness, and sustainability', 'HEC,AMBA,NBEAC', '2020-03-26 00:00:00', 424500, 'karachi School Of Business & Leadership, karachi', 11, NULL, 'https://www.ksbl.edu.pk', '2025-03-26 00:00:00', NULL);
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (29, 'Hannan', '2024-12-10 01:00:47.677189', NULL, NULL, 'National University of Technology (NUTECH) is a federally chartered Higher Education Commission (HEC), Pakistan Engineering Council (PEC), National Technology Council (NTC), National Computing Education Accreditation Council (NCEAC) and National Vocational & Technical Training Commission (NAVTTC) recognized Islamabadbased University, administratively under Ministry of Science & Technology (MoST). NUTECH is envisioned to be an internationally acclaimed technology driven research university destined to produce national and international industry future characterful leaders, professionals and hi-tech skilled workforce. The National University of Technology (NUTECH) is established as a pioneer ÔÇÿUniversity for IndustryÔÇÖ to create, develop, implement and promote existing, emerging and future technologies for the country through world-class education in science, engineering, technology, other technologies, professional certifications, technical & vocational skills and other areas of scholarship. The UniversityÔÇÖs curricula and academic systems are based on the best international practices of worldÔÇÖs leading technology universities of USA and EU. Its learning systems are designed to promote science, engineering and technology based knowledge eco-system to inspire the youth as promising entrepreneurs of tomorrow. The undergraduate programs of NUTECH satisfy Washington accord, ABET and Bologna Process. NUTECH is in the process of planning its main campus to house 20,000 ÔÇô 30,000 students in future.', 'HEC, PEC, NTC', '2025-07-07 00:00:00', 94444.44, 'National University Of Technology, Islamabad', 73, '2025-09-01 00:00:00', 'https://www.nutech.edu.pk', '2025-09-01 00:00:00', NULL);
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (30, 'Hannan', '2024-12-10 01:00:47.677189', NULL, NULL, 'Nestled in the serene setting of a beautiful countryside, Pakistan Institute of Engineering and Applied Sciences (PIEAS), Islamabad, is recognized as a preeminent federal public university devoted to higher education in specific disciplines of engineering, natural sciences and formal sciences. Although PIEAS offers BS, MS, MPhil and PhD degree programs, yet the postgraduate degree programs dominate. In addition to the degree programs, PIEAS also offers specialized short courses to engineers, scientists and other professionals for their continuing professional development. PIEAS highly qualified faculty matched with excellent infrastructure are instrumental in its endeavor to offer high quality education in the disciplines of engineering and applied sciences, fulfill national and regional requirements for highly qualified professionals and contribute to the welfare of humanity through education, research and development. The Institute has been ranked No. 1 for Engineering & Technology by the Higher Education Commission (HEC), Pakistan, in all the three rankings (2006, 2012, 2013) conducted so far.', 'HEC', '2024-05-24 00:00:00', 140000, 'Pakistan Institute Of Engineering & Applied Sciences, Islamabad', 25, '2025-09-09 00:00:00', 'https://www.pieas.edu.pk', '2025-09-09 00:00:00', NULL);
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (31, 'Hannan', '2024-12-10 01:00:47.677189', NULL, NULL, 'Riphah International University, Islamabadis a private University, chartered by the Federal Government of Pakistan in 2002. The University was established to produce professionals with Islamic moral and ethical values. It is sponsored by a not-for-profit trust; namely, Islamic International Medical College Trust (IIMCT), created in 1995. The first project of the IIMCT was the Islamic International Medical College, Rawalpindi, established in 1996 by its Founding Managing Trustee; Maj. Gen. (Retd.) Muhammad Zulfiqar Ali Khan, TI(M), TBt (Late).
