INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (33, 'Hannan', '2024-12-10 01:00:47.677189', NULL, NULL, 'SS-CASE-IT offers four-year Bachelor degrees in five domains of Computing (Artificial Intelligence, Computer Science, Cyber Security, Data Science, Software Engineering), Electrical and Computer Engineering, Business Administration, Accounting & Finance, Business Analytics, Financial Technology, English, and Mathematics.
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (34, 'Hannan', '2024-12-10 01:00:47.677189', NULL, NULL, 'Abasyn University was chartered in 2009 under the act of Legislative Provisional Assembly of KPK in 2009 and is recognized by the Higher Education Commission (HEC), Pakistan. Abasyn University was the only University in KPK which was awarded category ÔÇÿWÔÇÖ at the inception which was the highest category to be awarded to any institution in the old ranking system by HEC. By the grace of Allah and the support of sponsors and staff, HEC has upgraded category ÔÇÿWÔÇÖ to ÔÇÿW3ÔÇÖ in the new ranking system.
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (35, 'Hannan', '2024-12-10 01:00:47.677189', NULL, NULL, 'Al-Khair University was established in 1994, under an act number XXVIII of the Legislative Assembly of Azad Jammu & Kashmir. The Main objective for the establishment of the University in the Private Sector was to supplement the Public Sector Education, by disseminating professional, scientific and technological education in the Country. With a view, however, to keep pace with changing scenario of education globally, the main focus is in the field of Marketing, Banking & Finance, Information Technology and Computer Oriented courses.
