INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (61, 'Hannan', '2025-02-23 13:43:39.198966', NULL, NULL, 'The University of Peshawar, as a mother educational institution of Khyber Pakhtunkhwa is an outcome of the dream of the father of the nation and was created as the first ever University after independence. It is vigorously working with its full zeal and spirit, truly serving and sacred cause of education altogether.
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (62, 'Hannan', '2025-02-23 13:43:39.198966', NULL, NULL, 'Vision
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (64, 'Hannan', '2025-02-23 13:43:39.198966', NULL, NULL, 'Qurtuba University of Science and Information Technology is one of the pioneer private sector Universities of Khyber PakhtunKhwa Pakistan. The University was established through a charter issued by the Governor (K.P) on 30th August 2001 and is recognized by the Higher Education commission (former UGC), Islamabad. Qurtuba University of Science and Information Technology is one of the pioneer private sector Universities of Khyber PakhtunKhwa Pakistan. The University was established through a charter issued by the Governor (K.P) on 30th August 2001 and is recognized by the Higher Education commission (former UGC), Islamabad. The University has been working sincerely towards the attainment of character-building and cultivate in its students the quest for inquiry so that they may extend the frontiers of knowledge & be able to bring peace & prosperity to the country. Our goal is to revive the memories of the city of Cordova, known as "Madinat-Ul-Ilm". This city was known as the cradle of knowledge and research for centuries. European scholars & students also thronged to this seat of learning & acquired specializations in various fields of knowledge.', 'HEC, PEC', '2024-10-31 00:00:00', 72431.37, 'Qurtuba University Of Science & Information Technology, Peshawar', 139, NULL, 'https://www.qurtuba.edu.pk', '2024-10-31 00:00:00', NULL);
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (65, 'Hannan', '2025-02-23 13:43:39.198966', NULL, NULL, 'OUR VISION
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (66, 'Hannan', '2025-02-23 13:43:39.198966', NULL, NULL, 'The Buraq Institute of Higher Studies (BIHS) is a private educational institution located in Peshawar, Khyber Pakhtunkhwa, Pakistan. Established to provide quality education across various disciplines, BIHS offers undergraduate and postgraduate programs in fields such as Business Administration, Computer Science, and Social Sciences. The institute emphasizes a balanced approach to education, integrating theoretical knowledge with practical skills to prepare students for the competitive job market.', 'HEC', '2015-02-28 00:00:00', 75000, 'Buraq Institute Of Higher Studies, Peshawar', 250, NULL, 'https://www.bihs.edu.pk', '2015-02-28 00:00:00', NULL);
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (67, 'Hannan', '2025-02-23 13:43:39.198966', NULL, NULL, 'The Farkhanda Institute of Nursing and Public Health (FIN&PH), established in 1998, is a pioneering private nursing institution located in Peshawar, Khyber Pakhtunkhwa, Pakistan. Affiliated with Gandhara University, the institute offers a range of nursing and public health programs for both male and female students, emphasizing quality education and equitable access.', 'HEC,PNC', '2024-09-18 00:00:00', 90000, 'Farkhunda Institute Of Nursing And Public Health, Peshawar', 180, NULL, 'https://www.gandhara.edu.pk', '2024-09-18 00:00:00', NULL);
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (19, 'Hannan', '2024-12-10 01:00:47.677189', NULL, NULL, 'Baqai Medical University (BMU) is a prominent private institution established in 1996 under a bill passed by the Sindh Assembly, subsequently notified by the Governor of Sindh. Located in the rural setting of Gadap, karachi, the university spans a campus of 72 acres and includes seven blocks with a built-up area of 727,374 square feet. It houses 13 institutions, educates approximately 1,800 students, and offers 19 degrees and diplomas across various specialties. BMU employs over 1,000 individuals in diverse capacities, embodying its mission of community-based and community-oriented medical education.
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (55, 'Hannan', '2025-02-23 13:43:39.198966', NULL, NULL, 'Mission Statement
INSERT INTO public.university (id, created_by, created_date, last_modified_by, last_modified_date, about, accrediatetion_body, apply_date, average_fees, name, rank, start_date, website_link, entry_test_date, universitylocation_id) OVERRIDING SYSTEM VALUE VALUES (27, 'Hannan', '2024-12-10 01:00:47.677189', NULL, NULL, 'The National University of Modern Languages was established as an institute in 1969 to help people communicate and understand each other in different oriental and occidental languages, to assimilate different cultures and to act as springboard for emerging disciplines. Initially, the institute provided language training facilities to personnel of armed forces and other government services of Pakistan. It was upgraded to University on May 29, 2000. In achieving this benchmark of a fully autonomous University, it has crossed many barriers and achieved a status of a seat of learning contributing new knowledge in local and global perspective and now teaches 27 oriental and occidental languages in addition to a number of emerging disciplines. Now, the University has a vibrant and well-grounded research program, offering MS/MPhil and PhD research degrees in various disciplines.', 'HEC, NBEAC', '2024-12-24 00:00:00', 22982.92, 'National University Of Modern Languages, Islamabad, Islamabad', 126, '2025-02-03 00:00:00', 'https://www.numl.edu.pk', '2025-02-03 00:00:00', 23);
